import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:kmreader/core/kindle/client.dart';
import 'package:kmreader/core/kindle/conversion.dart';
import 'package:kmreader/core/kindle/positions.dart';
import 'package:kmreader/core/kindle/repository.dart';
import 'package:kmreader/core/store.dart';
import 'package:sqlite3/sqlite3.dart';
import 'package:kmreader/core/models.dart';
import 'package:xml/xml.dart';

/// Protocol discovery is confined to the EPUB generated by our upload probe.
/// No user publication or purchased book may reach the annotation write.
void main() {
  final path =
      Platform.environment['KMREADER_KINDLE_MANAGEMENT_PRIVATE_SESSION'];
  test(
    'generated PDOC bookmark write is checked against the actual cloud sidecar',
    () async {
      final report = <String, dynamic>{
        'schema': 1,
        'existing_documents_modified': 0,
        'document_deletions': 0,
        'annotation_writes': 0,
      };
      KindleClient? client;
      KindleRepository? repository;
      final root = Directory.systemTemp.createTempSync(
        'kindle-bookmark-probe-',
      );
      final store = LocalStore(sqlite3.openInMemory());
      try {
        final file = File(path!);
        final payload = object(jsonDecode(await file.readAsString()));
        final libraryFixture =
            Platform.environment['KMREADER_KINDLE_MANAGEMENT_FIXTURE'] ==
            'library';
        final fixture = object(
          libraryFixture
              ? object(payload['delivery_probes'])['library']
              : payload['probe_operation'],
        );
        final id = text(fixture['catalog_id']);
        if (id.isEmpty ||
            !text(fixture['title']).startsWith('KMReader test ')) {
          throw const KindleFailure('bookmark_probe_fixture_missing');
        }
        final journal = object(payload['management_probe']);
        payload['management_probe'] = journal;
        final bookmarkKey = libraryFixture
            ? 'bookmark_probe_library'
            : 'bookmark_probe';
        final bookmark = object(journal[bookmarkKey]);
        journal[bookmarkKey] = bookmark;
        Future<void> seal() async {
          await file.writeAsString(jsonEncode(payload));
          final process = await Process.run('python', [
            '-m',
            'tool.kindle_send_probe_bridge',
            'seal',
            file.path,
          ]);
          if (process.exitCode != 0) {
            throw const KindleFailure('bookmark_probe_journal');
          }
        }

        final transport = _BookmarkProbeClient(id, report);
        client = KindleClient(
          session: KindleSession(object(payload['session'])),
          client: transport,
        );
        final catalog = await client.catalog(full: true);
        final matches = (catalog['items'] as List)
            .map(object)
            .where(
              (item) =>
                  item['id'] == id &&
                  item['title'] == fixture['title'] &&
                  item['type'] == 'PDOC',
            );
        if (matches.length != 1) {
          throw const KindleFailure('bookmark_probe_identity');
        }
        final item = matches.single;
        NativeKindlePreparation.executableOverride =
            Platform.environment['KMREADER_KINDLE_WORKER'];
        final session = client.session!;
        repository = KindleRepository(
          profile: ServerProfile(
            id: session.id,
            name: 'Generated bookmark probe',
            url: 'https://www.amazon.it',
            email: '',
            source: 'kindle',
            authentication: Authentication.apiKey,
          ),
          store: store,
          directory: root,
          client: client,
        );
        await repository.library.refresh(full: true);
        final book = await repository.book(repository.library.idFor(item));
        await repository.download(book);
        final prepared = await repository.book(book.id);
        final mapping = await KindlePositionMap.open(
          repository.bookFile(prepared).path,
        );
        if (mapping == null ||
            mapping.primary == null ||
            mapping.entries.isEmpty) {
          throw const KindleFailure('bookmark_probe_mapping_missing');
        }
        final guid = mapping.primary!;
        final probePosition = integer(mapping.entries.first['position']);
        transport.guid = guid;
        transport.position = probePosition;
        report['verified_mapping_available'] = true;
        Json? sidecar;
        try {
          sidecar = await client.sidecar(item, guid: guid, annotations: true);
        } on KindleFailure catch (error) {
          if (error.status != 404) rethrow;
          report['initial_sidecar_missing'] = true;
        }
        bool confirmed(Json? value) => (value?['records'] as List? ?? [])
            .map(object)
            .any(
              (r) =>
                  r['type'] == 'kindle.bookmark' &&
                  num.tryParse('${r['startPosition']}') == probePosition,
            );
        if (!confirmed(sidecar) && bookmark.isEmpty) {
          bookmark['state'] = 'submitting';
          await seal();
          final timestamp =
              '${DateTime.now().toUtc().toIso8601String().split('.').first}+0000';
          // Build the complete document with one scoped create operation.
          final builder = XmlBuilder();
          builder.element(
            'annotations',
            attributes: {'version': '1.0', 'timestamp': timestamp},
            nest: () {
              builder.element(
                'book',
                attributes: {'key': id, 'type': 'PDOC', 'guid': guid},
                nest: () {
                  builder.element(
                    'bookmark',
                    attributes: {
                      'action': 'create',
                      'begin': '$probePosition',
                      'timestamp': timestamp,
                    },
                  );
                },
              );
            },
          );
          // Keep this experimental protocol out of the production manager until
          // a real write followed by readback has established its contract.
          final response = await client.request(
            Uri.https(
              'cde-ta-g7g.amazon.com',
              '/FionaCDEServiceEngine/sidecar',
              {'type': 'PDOC'},
            ),
            method: 'POST',
            body: utf8.encode(builder.buildDocument().toXmlString()),
            headers: {'Content-Type': 'application/xml'},
          );
          await response.stream.drain<void>().timeout(
            const Duration(seconds: 60),
          );
          bookmark['state'] = 'submitted';
          await seal();
          sidecar = await client.sidecar(item, guid: guid, annotations: true);
        }
        report['bookmark_confirmed'] = confirmed(sidecar);
        report['guid_present'] = text(sidecar?['guid']).isNotEmpty;
        report['record_shapes'] = [
          for (final r in (sidecar?['records'] as List? ?? []).map(object))
            {
              'type':
                  const {
                    'kindle.bookmark',
                    'kindle.highlight',
                    'kindle.note',
                    'kindle.lpr',
                    'kindle.most_recent_read',
                  }.contains(r['type'])
                  ? r['type']
                  : 'other',
              'start_type': r['startPosition'] == null
                  ? 'absent'
                  : r['startPosition'] is num
                  ? 'number'
                  : r['startPosition'] is String
                  ? 'string'
                  : 'other',
              'start_matches':
                  num.tryParse('${r['startPosition']}') == probePosition,
            },
        ];
        report['recognized_record_count'] =
            (sidecar?['records'] as List? ?? []).length;
        report['passed'] = report['bookmark_confirmed'] == true;
        bookmark['state'] = report['passed'] == true
            ? 'confirmed'
            : 'unconfirmed';
        await seal();
        if (report['passed'] != true) {
          fail('Bookmark protocol not confirmed. No replay.');
        }
      } catch (error) {
        report['passed'] = false;
        report['error_code'] = error is KindleFailure
            ? error.code
            : 'bookmark_probe';
        if (error is KindleFailure) report['http_status'] = error.status;
        fail('Bookmark check failed; inspect sanitized metrics.');
      } finally {
        await repository?.stopDownloadWork();
        repository?.dispose();
        client?.close();
        store.close();
        await root.delete(recursive: true);
        final output =
            Platform.environment['KMREADER_KINDLE_MANAGEMENT_REPORT'];
        if (output != null) {
          await File(output).writeAsString(jsonEncode(report));
        }
      }
    },
    skip: path == null || !Platform.isWindows,
    timeout: const Timeout(Duration(minutes: 6)),
  );
}

class _BookmarkProbeClient extends http.BaseClient {
  _BookmarkProbeClient(this.id, this.report);
  final String id;
  final Json report;
  final delegate = http.Client();
  int writes = 0;
  String? guid;
  int? position;
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) async {
    final uri = request.url;
    final sidecar =
        uri.host == 'cde-ta-g7g.amazon.com' &&
        uri.path == '/FionaCDEServiceEngine/sidecar';
    final read =
        request.method == 'GET' &&
        (sidecar && uri.queryParameters['key'] == id ||
            uri.host == 'todo-ta-g7g.amazon.com' &&
                uri.path == '/FionaTodoListProxy/syncMetaData' ||
            kindleAllowedUri(uri) && !sidecar);
    final auth =
        request.method == 'POST' &&
        uri.host == 'api.amazon.it' &&
        uri.path == '/auth/token';
    final write = request.method == 'POST' && sidecar;
    if (uri.scheme != 'https' ||
        uri.port != 443 ||
        uri.userInfo.isNotEmpty ||
        !(read || auth || write)) {
      throw const KindleFailure('bookmark_probe_guard');
    }
    if (write) {
      if (++writes > 1 || request is! http.Request) {
        throw const KindleFailure('bookmark_probe_limit');
      }
      final document = XmlDocument.parse(request.body);
      final books = document.findAllElements('book').toList();
      final marks = document.findAllElements('bookmark').toList();
      if (books.length != 1 ||
          books.single.getAttribute('key') != id ||
          books.single.getAttribute('type') != 'PDOC' ||
          books.single.getAttribute('guid') != guid ||
          books.single.childElements.length != 1 ||
          marks.length != 1 ||
          marks.single.getAttribute('action') != 'create' ||
          marks.single.getAttribute('begin') != '$position') {
        throw const KindleFailure('bookmark_probe_document_guard');
      }
      report['annotation_writes'] = writes;
    }
    final reply = await delegate.send(request);
    final steps = report['steps'] ??= <Json>[];
    (steps as List).add({
      'step': write
          ? 'create_test_bookmark'
          : uri.path.startsWith('/delivery/manifest/')
          ? 'fixture_manifest'
          : uri.path.startsWith('/delivery/')
          ? 'fixture_resource'
          : uri.path,
      'http_status': reply.statusCode,
    });
    return reply;
  }

  @override
  void close() => delegate.close();
}
